;------------------------------------------------------------------------------; Scripteur ......: Daniel Lafrance, Québec, canada.; Nom du fichier .: l-c64-joystick.asm; Cernière m.à j. : 20261030-000000 Francisation des commentaires,; Inspiration ....:;------------------------------------------------------------------------------;               .include "l-cbm-conv.asm";------------------------------------------------------------------------------; On prend une photo de tous les registres et on les place en mémoire.;------------------------------------------------------------------------------printregs      .macro               jsr   regsphoto               jsr   showregs               .endmregsphoto      .block               php                  ; Sauve le registre P. stack-> p, pch, pcl               sta   vrega          ; Sauve Acc en mémoire.               pla                  ; stack-> pcl, pch               sta   vregp          ; Sauve P en mémoire.               stx   vregx          ; Sauve X en mémoire.               sty   vregy          ; Sauve Y en mémoire.               tsx                  ; Copie S san X.               stx   vregs          ; Sauve S en mémoire.               pla                  ; Récupère pcl. stack-> pch                    sta   vregpcl        ; Sauve pcl en mémoire.                pla                  ; Récupère pch. stack->                sta   vregpch        ; Sauve pch en mémoire.               lda   vrega          ; conversion de A en hexadecimal               pha                  ; stack-> a               lda   zpage1               sta   vzp1l               lda   zpage1+1               sta   vzp1h               lda   zpage2               sta   vzp2l               lda   zpage2+1               sta   vzp2h               lda   vregpch               pha                  ; stack-> pch               lda   vregpcl               pha                  ; stack-> pcl, pch               ldy   vregy               ldx   vregx               lda   vregp               pha                  ; stack-> p, pcl, pch               lda   vrega               plp                  ; stack-> pcl, pch               rts               .bendline           =     23             ; Afficher les registre sur la ligne 23coln           =     0              ; ... à partir de la première colonnecolr           =     vblanc         ; ... dans un texte en blanc.showregs       .block               jsr   push               lda   vrega               jsr   putahexfmt               lda   vregx               jsr   putahexfmt               lda   vregy               jsr   putahexfmt               lda   vregp               jsr   putahexfmt               lda   vregs               jsr   putahexfmt               ldy   vregpch               ldx   vregpcl               jsr   yxtohex               jsr   putahexfmt               ldy   vzp1h               ldx   vzp1l               jsr   yxtohex               jsr   putahexfmt               ldy   vzp2h               ldx   vzp2l               jsr   yxtohex               jsr   putahexfmt               jsr   pop               rts               .bendvrega    .byte   0vregx    .byte   0vregy    .byte   0vregp    .byte   0vregs    .byte   0vregpch  .byte   0vregpcl  .byte   0vzp1h   .byte   0vzp1l   .byte   0vzp2h   .byte   0vzp2l   .byte   0